/**
 * adapter-generator: writes a member adapter for a coding CLI MerakCode has no adapter for, tests it and registers it
 * as a collaboration product. It writes the adapter; it does not add anyone to a group.
 *
 * Its files are in this folder: SKILL.md, and the adapter library and examples generated by pnpm
 * generate:adapter-library. A release has the folder in lib/skills/ and reads it from there.
 */
import { existsSync, readFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

/** Where the folder is: beside the bundled engine in a release, here in a source checkout */
function folder(here = import.meta.url) {
  const bundled = fileURLToPath(new URL("./skills/adapter-generator", here))
  return existsSync(bundled) ? bundled : fileURLToPath(new URL("./", here))
}

const dir = folder()
const read = (file: string) => readFileSync(path.join(dir, file), "utf8")
const FILES = [
  "merakcode-adapter.mjs",
  "merakcode-adapter.d.mts",
  "example-claude-code.mts",
  "example-codex.mts",
  "example-opencode.mts",
]

export const ADAPTER_GENERATOR_SKILL = {
  name: "adapter-generator",
  description:
    "Write a member adapter that lets MerakCode collaboration groups use a coding CLI it has no adapter for (the user's own AI coding tool, or one without official support): study the CLI, write and test the adapter from MerakCode's own adapters, and register it as a product. Writes the adapter only; it does not add members to a group",
  content: read("SKILL.md"),
  files: Object.fromEntries(FILES.map((file) => [file, read(file)])),
  dir,
}
